CREATE OR REPLACE FUNCTION public.is_house_admin(p_house_id UUID, p_user_id UUID)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
STABLE
SET search_path = public
AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1
    FROM house_members
    WHERE house_id = p_house_id
      AND user_id = p_user_id
      AND role IN ('Owner', 'Admin')
  );
END;
$$;

