);

CREATE POLICY "Admins can update members"
ON house_members
FOR UPDATE
TO authenticated
USING (
  role <> 'Owner'
  AND public.is_house_admin(house_members.house_id, auth.uid())
)
WITH CHECK (
  role <> 'Owner'
  AND public.is_house_admin(house_members.house_id, auth.uid())
);

CREATE POLICY "Admins can delete members"
