DROP POLICY IF EXISTS "Members can view house members" ON house_members;
DROP POLICY IF EXISTS "Members can insert themselves" ON house_members;
DROP POLICY IF EXISTS "Admins can delete members" ON house_members;
DROP POLICY IF EXISTS "Admins can update members" ON house_members;

DROP POLICY IF EXISTS "Members can view house config" ON house_config;
DROP POLICY IF EXISTS "Admins can insert house config" ON house_config;
DROP POLICY IF EXISTS "Admins can update house config" ON house_config;
DROP POLICY IF EXISTS "Owners can delete house config" ON house_config;

-- Enable RLS
ALTER TABLE houses ENABLE ROW LEVEL SECURITY;
ALTER TABLE house_members ENABLE ROW LEVEL SECURITY;
ALTER TABLE house_config ENABLE ROW LEVEL SECURITY;

-- HOUSES policies
CREATE POLICY "Users can view their houses"
    ON houses FOR SELECT
    USING (
        EXISTS (
            SELECT 1 FROM house_members
            WHERE house_members.house_id = houses.id
              AND house_members.user_id = auth.uid()
        )
    );

CREATE POLICY "Users can create houses"
    ON houses FOR INSERT
    WITH CHECK (auth.uid() IS NOT NULL);

CREATE POLICY "Owners can update houses"
    ON houses FOR UPDATE
    USING (owner_id = auth.uid());

CREATE POLICY "Owners can delete houses"
    ON houses FOR DELETE
    USING (owner_id = auth.uid());

-- HOUSE_MEMBERS policies (FIXED - No recursion)
CREATE POLICY "Members can view house members"
    ON house_members FOR SELECT
    USING (
        user_id = auth.uid()
        OR
        EXISTS (
            SELECT 1
            FROM house_members AS my_membership
            WHERE my_membership.user_id = auth.uid()
              AND my_membership.house_id = house_members.house_id
        )
    );

CREATE POLICY "Members can insert themselves"
    ON house_members FOR INSERT
    WITH CHECK (user_id = auth.uid());

CREATE POLICY "Admins can update members"
    ON house_members FOR UPDATE
    USING (
        role != 'Owner'
        AND
        EXISTS (
            SELECT 1 FROM house_members AS my_membership
            WHERE my_membership.user_id = auth.uid()
              AND my_membership.house_id = house_members.house_id
              AND my_membership.role IN ('Owner', 'Admin')
        )
    );

CREATE POLICY "Admins can delete members"
    ON house_members FOR DELETE
    USING (
        role != 'Owner'
        AND
        EXISTS (
            SELECT 1 FROM house_members AS my_membership
            WHERE my_membership.user_id = auth.uid()
              AND my_membership.house_id = house_members.house_id
              AND my_membership.role IN ('Owner', 'Admin')
        )
    );

-- HOUSE_CONFIG policies
CREATE POLICY "Members can view house config"
    ON house_config FOR SELECT
    USING (
        EXISTS (
            SELECT 1 FROM house_members
            WHERE house_members.house_id = house_config.house_id
              AND house_members.user_id = auth.uid()
        )
    );

CREATE POLICY "Admins can insert house config"
    ON house_config FOR INSERT
    WITH CHECK (
        EXISTS (
            SELECT 1 FROM house_members
            WHERE house_members.house_id = house_config.house_id
              AND house_members.user_id = auth.uid()
              AND house_members.role IN ('Owner', 'Admin')
        )
    );

CREATE POLICY "Admins can update house config"
    ON house_config FOR UPDATE
    USING (
        EXISTS (
            SELECT 1 FROM house_members
            WHERE house_members.house_id = house_config.house_id
              AND house_members.user_id = auth.uid()
              AND house_members.role IN ('Owner', 'Admin')
        )
    );

CREATE POLICY "Owners can delete house config"
    ON house_config FOR DELETE
    USING (
        EXISTS (
            SELECT 1 FROM house_members
            WHERE house_members.house_id = house_config.house_id
              AND house_members.user_id = auth.uid()
              AND house_members.role = 'Owner'
        )
    );

