        EXISTS (
            SELECT 1 FROM house_members
            WHERE house_members.house_id = one_time_expenses.house_id
              AND house_members.user_id = auth.uid()
        )
    );

CREATE POLICY "Members can create expenses"
    ON one_time_expenses FOR INSERT
    WITH CHECK (
        paid_by = auth.uid()
        AND
        EXISTS (
            SELECT 1 FROM house_members
            WHERE house_members.house_id = one_time_expenses.house_id
              AND house_members.user_id = auth.uid()
        )
    );

CREATE POLICY "Members can update own expenses"
    ON one_time_expenses FOR UPDATE
    USING (
        paid_by = auth.uid()
        OR
        EXISTS (
            SELECT 1 FROM house_members
            WHERE house_members.house_id = one_time_expenses.house_id
              AND house_members.user_id = auth.uid()
              AND house_members.role IN ('Owner', 'Admin')
        )
    );

CREATE POLICY "Admins can delete expenses"
    ON one_time_expenses FOR DELETE
    USING (
        EXISTS (
            SELECT 1 FROM house_members
            WHERE house_members.house_id = one_time_expenses.house_id
              AND house_members.user_id = auth.uid()
              AND house_members.role IN ('Owner', 'Admin')
        )
    );

-- EXPENSE_SPLITS policies
CREATE POLICY "Members can view expense splits"
    ON expense_splits FOR SELECT
    USING (
        EXISTS (
            SELECT 1 FROM one_time_expenses e
            JOIN house_members hm ON hm.house_id = e.house_id
            WHERE e.id = expense_splits.expense_id
              AND hm.user_id = auth.uid()
        )
    );

CREATE POLICY "Admins can insert expense splits"
    ON expense_splits FOR INSERT
    WITH CHECK (
        EXISTS (
            SELECT 1 FROM one_time_expenses e
            JOIN house_members hm ON hm.house_id = e.house_id
            WHERE e.id = expense_splits.expense_id
              AND hm.user_id = auth.uid()
        )
    );

CREATE POLICY "Admins can update expense splits"
    ON expense_splits FOR UPDATE
    USING (
        EXISTS (
            SELECT 1 FROM one_time_expenses e
            JOIN house_members hm ON hm.house_id = e.house_id
            WHERE e.id = expense_splits.expense_id
              AND hm.user_id = auth.uid()
              AND hm.role IN ('Owner', 'Admin')
        )
    );

CREATE POLICY "Admins can delete expense splits"
    ON expense_splits FOR DELETE
    USING (
        EXISTS (
            SELECT 1 FROM one_time_expenses e
            JOIN house_members hm ON hm.house_id = e.house_id
            WHERE e.id = expense_splits.expense_id
              AND hm.user_id = auth.uid()
              AND hm.role IN ('Owner', 'Admin')
        )
    );

