ALTER TABLE documents ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users can view own personal documents"
    ON documents FOR SELECT
    USING (
        house_id IS NULL
        AND user_id = auth.uid()
    );

CREATE POLICY "Members can view house documents"
    ON documents FOR SELECT
    USING (
        house_id IS NOT NULL
        AND
        EXISTS (
            SELECT 1 FROM house_members
            WHERE house_members.house_id = documents.house_id
              AND house_members.user_id = auth.uid()
        )
    );

CREATE POLICY "Users can upload documents"
    ON documents FOR INSERT
    WITH CHECK (
        user_id = auth.uid()
        AND (
            house_id IS NULL
            OR
            EXISTS (
                SELECT 1 FROM house_members
                WHERE house_members.house_id = documents.house_id
                  AND house_members.user_id = auth.uid()
            )
        )
    );

CREATE POLICY "Users and admins can delete documents"
    ON documents FOR DELETE
    USING (
        user_id = auth.uid()
        OR
        (
            house_id IS NOT NULL
            AND
            EXISTS (
                SELECT 1 FROM house_members
                WHERE house_members.house_id = documents.house_id
                  AND house_members.user_id = auth.uid()
                  AND house_members.role IN ('Owner', 'Admin')
            )
        )
    );

