ALTER PUBLICATION supabase_realtime ADD TABLE IF NOT EXISTS house_config;
ALTER PUBLICATION supabase_realtime ADD TABLE IF NOT EXISTS per_diem_entries;
ALTER PUBLICATION supabase_realtime ADD TABLE IF NOT EXISTS transactions;

-- Verify which tables are enabled for realtime
SELECT
    schemaname as schema,
    tablename as table,
    'Enabled ✓' as status
FROM pg_publication_tables
WHERE pubname = 'supabase_realtime'
ORDER BY tablename;

-- Count enabled tables
DO $$
DECLARE
    table_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO table_count
    FROM pg_publication_tables
    WHERE pubname = 'supabase_realtime';

    RAISE NOTICE '========================================';
    RAISE NOTICE '✅ REALTIME SETUP COMPLETE!';
    RAISE NOTICE '========================================';
    RAISE NOTICE 'Enabled realtime for % tables', table_count;
    RAISE NOTICE '';
    RAISE NOTICE 'Tables now broadcasting changes:';
    RAISE NOTICE '  ✓ notifications';
    RAISE NOTICE '  ✓ messages';
    RAISE NOTICE '  ✓ shopping_items';
    RAISE NOTICE '  ✓ chores';
    RAISE NOTICE '  ✓ one_time_expenses & recurring_expenses';
    RAISE NOTICE '  ✓ expense_splits';
    RAISE NOTICE '  ✓ house_members & houses';
    RAISE NOTICE '  ✓ documents';
    RAISE NOTICE '  ✓ house_config';
    RAISE NOTICE '  ✓ per_diem_entries';
    RAISE NOTICE '  ✓ transactions';
    RAISE NOTICE '';
    RAISE NOTICE 'Your app will now receive real-time updates!';
    RAISE NOTICE '========================================';
END $$;

-- ============================================================================ -- FIX: Infinite Recursion in house_members RLS Policies -- ============================================================================ -- Problem: The SELECT policy on house_members references itself, causing -- infinite recursion when trying to check if a user is a member of a house. -- -- Solution: Use auth.uid() directly without subqueries that reference the -- same table, or use SECURITY DEFINER functions to break the recursion chain. -- ============================================================================
-- Step 1: Drop existing problematic policies DROP POLICY IF EXISTS "Members can view house members" ON house_members; DROP POLICY IF EXISTS "Admins can update members" ON house_members; DROP POLICY IF EXISTS "Admins can delete members" ON house_members; DROP POLICY IF EXISTS "Members can insert themselves" ON house_members;
-- ============================================================================ -- Step 2: Create helper function to check membership (breaks recursion) -- ============================================================================ -- This function uses SECURITY DEFINER to bypass RLS and break the recursion CREATE OR REPLACE FUNCTION public.is_house_member(p_house_id UUID, p_user_id UUID) RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER STABLE AS $$ BEGIN RETURN EXISTS ( SELECT 1 FROM house_members WHERE house_id = p_house_id AND user_id = p_user_id ); END; $$;
-- ============================================================================ -- Step 3: Create helper function to check admin/owner role -- ============================================================================ CREATE OR REPLACE FUNCTION public.is_house_admin(p_house_id UUID, p_user_id UUID) RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER STABLE AS $$ BEGIN RETURN EXISTS ( SELECT 1 FROM house_members WHERE house_id = p_house_id AND user_id = p_user_id AND role IN ('Owner', 'Admin') ); END; $$;
-- ============================================================================ -- Step 4: Create new RLS policies using helper functions -- ============================================================================
-- SELECT Policy: Allow users to see members of houses they belong to CREATE POLICY "Members can view house members" ON house_members FOR SELECT USING ( -- User can see their own membership user_id = auth.uid() OR -- User is the house owner EXISTS ( SELECT 1 FROM houses h WHERE h.id = house_members.house_id AND h.owner_id = auth.uid() ) OR -- User is a member of this house (using helper function to avoid recursion) is_house_member(house_members.house_id, auth.uid()) );
-- INSERT Policy: Allow users to insert themselves as members CREATE POLICY "Members can insert themselves" ON house_members FOR INSERT WITH CHECK ( user_id = auth.uid() );
-- UPDATE Policy: Admins and owners can update members (except owner role) CREATE POLICY "Admins can update members" ON house_members FOR UPDATE USING ( -- Cannot change owner role role <> 'Owner' AND -- User must be admin or owner of this house is_house_admin(house_members.house_id, auth.uid()) ) WITH CHECK ( -- Cannot change someone to owner role role <> 'Owner' AND -- User must be admin or owner of this house is_house_admin(house_members.house_id, auth.uid()) );
-- DELETE Policy: Admins and owners can delete members (except owner) CREATE POLICY "Admins can delete members" ON house_members FOR DELETE USING ( -- Cannot delete owner role <> 'Owner' AND -- User must be admin or owner of this house is_house_admin(house_members.house_id, auth.uid()) );
-- ============================================================================ -- Step 5: Grant execute permissions on helper functions -- ============================================================================ GRANT EXECUTE ON FUNCTION public.is_house_member(UUID, UUID) TO authenticated; GRANT EXECUTE ON FUNCTION public.is_house_admin(UUID, UUID) TO authenticated;
-- ============================================================================ -- Step 6: Verify the policies -- ============================================================================ -- Check that policies are correctly created SELECT schemaname, tablename, policyname, cmd, qual FROM pg_policies WHERE tablename = 'house_members' ORDER BY cmd, policyname;
-- Test the helper functions SELECT 'is_house_member test' as test, auth.uid() as current_user;
-- ============================================================================ -- DONE! The infinite recursion should now be fixed. -- ============================================================================

-- ============================================================================ -- ALTERNATIVE FIX: Simpler approach without helper functions -- ============================================================================ -- This approach simplifies the policies to avoid recursion by only checking -- direct relationships without subqueries on the same table. -- ============================================================================
-- Step 1: Drop existing problematic policies DROP POLICY IF EXISTS "Members can view house members" ON house_members; DROP POLICY IF EXISTS "Admins can update members" ON house_members; DROP POLICY IF EXISTS "Admins can delete members" ON house_members; DROP POLICY IF EXISTS "Members can insert themselves" ON house_members;
-- ============================================================================ -- Step 2: Create simplified policies -- ============================================================================
-- SELECT Policy: Simple approach - users can see members of houses they own -- or their own membership records CREATE POLICY "Members can view house members" ON house_members FOR SELECT USING ( -- User can see their own membership user_id = auth.uid() OR -- User is the house owner EXISTS ( SELECT 1 FROM houses h WHERE h.id = house_members.house_id AND h.owner_id = auth.uid() ) );
-- INSERT Policy: Allow users to insert themselves as members CREATE POLICY "Members can insert themselves" ON house_members FOR INSERT WITH CHECK ( user_id = auth.uid() );
-- UPDATE Policy: Only house owners can update members (simplified) CREATE POLICY "Owners can update members" ON house_members FOR UPDATE USING ( -- Cannot change owner role role <> 'Owner' AND -- Only the house owner can update EXISTS ( SELECT 1 FROM houses h WHERE h.id = house_members.house_id AND h.owner_id = auth.uid() ) ) WITH CHECK ( -- Cannot change someone to owner role role <> 'Owner' AND -- Only the house owner can update EXISTS ( SELECT 1 FROM houses h WHERE h.id = house_members.house_id AND h.owner_id = auth.uid() ) );
-- DELETE Policy: Only house owners can delete members (simplified) CREATE POLICY "Owners can delete members" ON house_members FOR DELETE USING ( -- Cannot delete owner role <> 'Owner' AND -- Only the house owner can delete EXISTS ( SELECT 1 FROM houses h WHERE h.id = house_members.house_id AND h.owner_id = auth.uid() ) );
-- ============================================================================ -- Step 3: If you need admins to also manage members, use this approach instead -- ============================================================================ -- This uses a self-join pattern that PostgreSQL can optimize without recursion
-- Drop the simplified policies first -- DROP POLICY IF EXISTS "Members can view house members" ON house_members; -- DROP POLICY IF EXISTS "Owners can update members" ON house_members; -- DROP POLICY IF EXISTS "Owners can delete members" ON house_members;
-- SELECT with admin support (using self-join) -- CREATE POLICY "Members can view house members" -- ON house_members AS restrictive -- FOR SELECT -- USING ( -- user_id = auth.uid() -- OR -- house_id IN ( -- SELECT DISTINCT house_id -- FROM house_members -- WHERE user_id = auth.uid() -- ) -- );
-- Note: The above might still cause recursion in some PostgreSQL versions. -- The safest approach is to use SECURITY DEFINER functions (first script) -- or keep policies simple (only owners can manage, shown above).
-- ============================================================================ -- Verify the policies -- ============================================================================ SELECT schemaname, tablename, policyname, cmd, qual FROM pg_policies WHERE tablename = 'house_members' ORDER BY cmd, policyname;
